base=np.column_stack([np.ones_like(x),x,x**2,x**3,v,v**2,x*v])
c0,_,_,_=np.linalg.lstsq(base,dv_dt,rcond=None)
r0=dv_dt-base@c0
def score(B):
    cb,_,_,_=np.linalg.lstsq(B,r0,rcond=None)
    return 1-np.sum((r0-B@cb)**2)/np.sum((r0-r0.mean())**2)
res={}
for name,f in [("chirp_t2",lambda w:[np.sin(w*t**2),np.cos(w*t**2)]),
               ("t*sin",lambda w:[t*np.sin(w*t),t*np.cos(w*t)]),
               ("sin_t_plus_t",lambda w:[np.sin(w*t),np.cos(w*t),t])]:
    best=(-1,0)
    for w in np.linspace(0.05,8,1600):
        B=np.column_stack(f(w)); s=score(B)
        if s>best[0]: best=(s,w)
    res[name]=best
